-- Phase 3: multi-warehouse inventory. Additive only; no seed or balance backfill.
create sequence if not exists public.inventory_movement_number_seq;
create table if not exists public.inventory_warehouses(id uuid primary key default gen_random_uuid(),warehouse_code text not null unique,warehouse_name text not null,location text,active boolean not null default true,allow_negative boolean not null default false,created_at timestamptz not null default now(),created_by uuid references auth.users(id),updated_at timestamptz not null default now(),updated_by uuid references auth.users(id));
create table if not exists public.inventory_categories(id uuid primary key default gen_random_uuid(),category_code text not null unique,category_name text not null,parent_id uuid references public.inventory_categories(id),active boolean not null default true,created_at timestamptz not null default now(),created_by uuid references auth.users(id));
create table if not exists public.inventory_items(id uuid primary key default gen_random_uuid(),sku text not null unique,barcode text unique,item_name text not null,category_id uuid references public.inventory_categories(id),unit text not null default 'EA',size text,track_batch boolean not null default false,track_serial boolean not null default false,minimum_quantity numeric not null default 0 check(minimum_quantity>=0),reorder_quantity numeric not null default 0 check(reorder_quantity>=0),active boolean not null default true,created_at timestamptz not null default now(),created_by uuid references auth.users(id),updated_at timestamptz not null default now(),updated_by uuid references auth.users(id));
create table if not exists public.inventory_balances(warehouse_id uuid not null references public.inventory_warehouses(id),item_id uuid not null references public.inventory_items(id),quantity numeric not null default 0 check(quantity>=0),average_cost_piasters bigint not null default 0 check(average_cost_piasters>=0),updated_at timestamptz not null default now(),primary key(warehouse_id,item_id));
create table if not exists public.inventory_movements(id uuid primary key default gen_random_uuid(),movement_number text not null unique default('INV-'||to_char(current_date,'YYYY')||'-'||lpad(nextval('public.inventory_movement_number_seq')::text,7,'0')),movement_date date not null default current_date,movement_type text not null check(movement_type in('RECEIPT','ISSUE','RETURN_IN','RETURN_OUT','TRANSFER','ADJUSTMENT_IN','ADJUSTMENT_OUT','DAMAGE','WASTE','COUNT')),from_warehouse_id uuid references public.inventory_warehouses(id),to_warehouse_id uuid references public.inventory_warehouses(id),status text not null default 'DRAFT' check(status in('DRAFT','SUBMITTED','POSTED','REJECTED','REVERSED')),source_table text,source_id uuid,idempotency_key text unique,reason text,document_urls text[] not null default '{}',submitted_at timestamptz,submitted_by uuid references auth.users(id),posted_at timestamptz,posted_by uuid references auth.users(id),reversal_of uuid references public.inventory_movements(id),created_at timestamptz not null default now(),created_by uuid references auth.users(id),updated_at timestamptz not null default now(),updated_by uuid references auth.users(id),check(from_warehouse_id is not null or to_warehouse_id is not null));
create unique index if not exists inventory_movement_source_uq on public.inventory_movements(source_table,source_id) where source_table is not null and source_id is not null and reversal_of is null;
create table if not exists public.inventory_movement_lines(id uuid primary key default gen_random_uuid(),movement_id uuid not null references public.inventory_movements(id),item_id uuid not null references public.inventory_items(id),quantity numeric not null check(quantity>0),unit_cost_piasters bigint not null default 0 check(unit_cost_piasters>=0),batch_number text,serial_number text,expiry_date date,notes text,unique(movement_id,item_id,batch_number,serial_number));
create table if not exists public.inventory_counts(id uuid primary key default gen_random_uuid(),count_number text not null unique,warehouse_id uuid not null references public.inventory_warehouses(id),count_date date not null,status text not null default 'DRAFT' check(status in('DRAFT','SUBMITTED','APPROVED','POSTED','CANCELLED')),notes text,created_at timestamptz not null default now(),created_by uuid references auth.users(id),approved_at timestamptz,approved_by uuid references auth.users(id));
create table if not exists public.inventory_count_lines(id uuid primary key default gen_random_uuid(),count_id uuid not null references public.inventory_counts(id),item_id uuid not null references public.inventory_items(id),system_quantity numeric not null,physical_quantity numeric not null,variance numeric generated always as(physical_quantity-system_quantity) stored,unique(count_id,item_id));

alter table public.purchase_order_lines add column if not exists inventory_item_id uuid references public.inventory_items(id);
alter table public.goods_receipt_lines add column if not exists inventory_item_id uuid references public.inventory_items(id);
alter table public.goods_receipt_lines add column if not exists warehouse_id uuid references public.inventory_warehouses(id);

do $$declare t text;begin foreach t in array array['inventory_warehouses','inventory_categories','inventory_items','inventory_balances','inventory_movements','inventory_movement_lines','inventory_counts','inventory_count_lines'] loop execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from anon,authenticated',t);execute format('grant select on public.%I to authenticated',t);execute format('create policy %I on public.%I for select to authenticated using(public.current_finance_role() in (''OWNER'',''CEO'',''FINANCE_MANAGER'',''ACCOUNTANT'',''TREASURY'',''AUDITOR''))',t||'_read',t);end loop;end$$;
grant insert,update on public.inventory_warehouses,public.inventory_categories,public.inventory_items,public.inventory_movements,public.inventory_movement_lines,public.inventory_counts,public.inventory_count_lines to authenticated;
create policy inventory_master_write on public.inventory_warehouses for all to authenticated using(public.current_finance_role() in('OWNER','FINANCE_MANAGER')) with check(public.current_finance_role() in('OWNER','FINANCE_MANAGER'));
create policy inventory_category_write on public.inventory_categories for all to authenticated using(public.current_finance_role() in('OWNER','FINANCE_MANAGER')) with check(public.current_finance_role() in('OWNER','FINANCE_MANAGER'));
create policy inventory_item_write on public.inventory_items for all to authenticated using(public.current_finance_role() in('OWNER','FINANCE_MANAGER')) with check(public.current_finance_role() in('OWNER','FINANCE_MANAGER'));
create policy inventory_movement_draft_write on public.inventory_movements for all to authenticated using(status='DRAFT' and public.current_finance_role() in('OWNER','FINANCE_MANAGER','ACCOUNTANT','TREASURY')) with check(status='DRAFT' and public.current_finance_role() in('OWNER','FINANCE_MANAGER','ACCOUNTANT','TREASURY'));
create policy inventory_line_draft_write on public.inventory_movement_lines for all to authenticated using(public.current_finance_role() in('OWNER','FINANCE_MANAGER','ACCOUNTANT','TREASURY') and exists(select 1 from public.inventory_movements m where m.id=movement_id and m.status='DRAFT')) with check(public.current_finance_role() in('OWNER','FINANCE_MANAGER','ACCOUNTANT','TREASURY') and exists(select 1 from public.inventory_movements m where m.id=movement_id and m.status='DRAFT'));
create policy inventory_count_draft_write on public.inventory_counts for all to authenticated using(status='DRAFT' and public.current_finance_role() in('OWNER','FINANCE_MANAGER','ACCOUNTANT')) with check(status='DRAFT' and public.current_finance_role() in('OWNER','FINANCE_MANAGER','ACCOUNTANT'));
create policy inventory_count_line_write on public.inventory_count_lines for all to authenticated using(public.current_finance_role() in('OWNER','FINANCE_MANAGER','ACCOUNTANT') and exists(select 1 from public.inventory_counts c where c.id=count_id and c.status='DRAFT')) with check(public.current_finance_role() in('OWNER','FINANCE_MANAGER','ACCOUNTANT') and exists(select 1 from public.inventory_counts c where c.id=count_id and c.status='DRAFT'));

create or replace function public.submit_inventory_movement(p_movement uuid) returns void language plpgsql security definer set search_path='public','private','pg_temp' as $$begin if public.current_finance_role() not in('OWNER','FINANCE_MANAGER','ACCOUNTANT','TREASURY') then raise exception 'Not authorized';end if;update public.inventory_movements set status='SUBMITTED',submitted_at=now(),submitted_by=auth.uid(),updated_at=now(),updated_by=auth.uid() where id=p_movement and status='DRAFT';if not found then raise exception 'Movement is not DRAFT';end if;if not exists(select 1 from public.inventory_movement_lines where movement_id=p_movement) then raise exception 'Movement has no lines';end if;insert into public.audit_events(table_name,record_id,action,new_data,changed_by)values('inventory_movements',p_movement::text,'SUBMIT',jsonb_build_object('status','SUBMITTED'),auth.uid());end$$;
create or replace function public.post_inventory_movement(p_movement uuid) returns void language plpgsql security definer set search_path='public','private','pg_temp' as $$declare m public.inventory_movements%rowtype;l record;b public.inventory_balances%rowtype;incoming boolean;begin if public.current_finance_role() not in('OWNER','FINANCE_MANAGER') then raise exception 'Not authorized';end if;select * into m from public.inventory_movements where id=p_movement for update;if m.status<>'SUBMITTED' then raise exception 'Movement is not SUBMITTED';end if;for l in select * from public.inventory_movement_lines where movement_id=m.id order by id loop incoming:=m.movement_type in('RECEIPT','RETURN_IN','ADJUSTMENT_IN');if m.movement_type='TRANSFER' then insert into public.inventory_balances(warehouse_id,item_id)values(m.from_warehouse_id,l.item_id)on conflict do nothing;select * into b from public.inventory_balances where warehouse_id=m.from_warehouse_id and item_id=l.item_id for update;if b.quantity<l.quantity then raise exception 'Negative stock is forbidden';end if;update public.inventory_balances set quantity=quantity-l.quantity,updated_at=now() where warehouse_id=m.from_warehouse_id and item_id=l.item_id;insert into public.inventory_balances(warehouse_id,item_id,quantity,average_cost_piasters)values(m.to_warehouse_id,l.item_id,l.quantity,b.average_cost_piasters)on conflict(warehouse_id,item_id) do update set average_cost_piasters=case when inventory_balances.quantity+excluded.quantity=0 then 0 else ((inventory_balances.quantity*inventory_balances.average_cost_piasters)+(excluded.quantity*excluded.average_cost_piasters))/(inventory_balances.quantity+excluded.quantity) end,quantity=inventory_balances.quantity+excluded.quantity,updated_at=now();elsif incoming then insert into public.inventory_balances(warehouse_id,item_id,quantity,average_cost_piasters)values(m.to_warehouse_id,l.item_id,l.quantity,l.unit_cost_piasters)on conflict(warehouse_id,item_id) do update set average_cost_piasters=case when inventory_balances.quantity+excluded.quantity=0 then 0 else ((inventory_balances.quantity*inventory_balances.average_cost_piasters)+(excluded.quantity*excluded.average_cost_piasters))/(inventory_balances.quantity+excluded.quantity) end,quantity=inventory_balances.quantity+excluded.quantity,updated_at=now();else insert into public.inventory_balances(warehouse_id,item_id)values(m.from_warehouse_id,l.item_id)on conflict do nothing;select * into b from public.inventory_balances where warehouse_id=m.from_warehouse_id and item_id=l.item_id for update;if b.quantity<l.quantity then raise exception 'Negative stock is forbidden';end if;update public.inventory_balances set quantity=quantity-l.quantity,updated_at=now() where warehouse_id=m.from_warehouse_id and item_id=l.item_id;end if;end loop;update public.inventory_movements set status='POSTED',posted_at=now(),posted_by=auth.uid(),updated_at=now(),updated_by=auth.uid() where id=m.id;insert into public.audit_events(table_name,record_id,action,new_data,changed_by)values('inventory_movements',m.id::text,'POST',jsonb_build_object('status','POSTED','type',m.movement_type),auth.uid());end$$;
revoke all on function public.submit_inventory_movement(uuid),public.post_inventory_movement(uuid) from public,anon;grant execute on function public.submit_inventory_movement(uuid),public.post_inventory_movement(uuid) to authenticated;

create or replace view public.v_inventory_stock_card with(security_invoker=true) as select m.movement_date,m.movement_number,m.movement_type,m.status,m.from_warehouse_id,m.to_warehouse_id,l.item_id,l.quantity,l.unit_cost_piasters,l.batch_number,l.serial_number,m.source_table,m.source_id,m.posted_at from public.inventory_movements m join public.inventory_movement_lines l on l.movement_id=m.id;
grant select on public.v_inventory_stock_card to authenticated;
